{"command":"cat > main.c <<'EOF'
#include <stdio.h>
#include <string.h>

const char *help_text =
"Usage:\n"
"    age [--encrypt] (-r RECIPIENT | -R PATH)... [--armor] [-o OUTPUT] [INPUT]\n"
"    age [--encrypt] --passphrase [--armor] [-o OUTPUT] [INPUT]\n"
"    age --decrypt [-i PATH]... [-o OUTPUT] [INPUT]\n\n"
"Options:\n"
"    -e, --encrypt               Encrypt the input to the output. Default if omitted.\n"
"    -d, --decrypt               Decrypt the input to the output.\n"
"    -o, --output OUTPUT         Write the result to the file at path OUTPUT.\n"
"    -a, --armor                 Encrypt to a PEM encoded format.\n"
"    -p, --passphrase            Encrypt with a passphrase.\n"
"    -r, --recipient RECIPIENT   Encrypt to the specified RECIPIENT. Can be repeated.\n"
"    -R, --recipients-file PATH  Encrypt to recipients listed at PATH. Can be repeated.\n"
"    -i, --identity PATH         Use the identity file at PATH. Can be repeated.\n\n"
"INPUT defaults to standard input, and OUTPUT defaults to standard output.\n"
"If OUTPUT exists, it will be overwritten.\n\n"
"RECIPIENT can be an age public key generated by age-keygen (\"age1...\")\n"
"or an SSH public key (\"ssh-ed25519 AAAA...\", \"ssh-rsa AAAA...\").\n\n"
"Recipient files contain one or more recipients, one per line. Empty lines\n"
"and lines starting with \"#\" are ignored as comments. \"-\" may be used to\n"
"read recipients from standard input.\n\n"
"Identity files contain one or more secret keys (\"AGE-SECRET-KEY-1...\"),\n"
"one per line, or an SSH key. Empty lines and lines starting with \"#\" are\n"
"ignored as comments. Passphrase encrypted age files can be used as\n"
"identity files. Multiple key files can be provided, and any unused ones\n"
"will be ignored. \"-\" may be used to read identities from standard input.\n\n"
"When --encrypt is specified explicitly, -i can also be used to encrypt to an\n"
"identity file symmetrically, instead or in addition to normal recipients.\n\n"
"Example:\n"
"    $ age-keygen -o key.txt\n"
"    Public key: age1ql3z7hjy54pw3hyww5ayyfg7zqgvc7w3j2elw8zmrj2kg5sfn9aqmcac8p\n"
"    $ tar cvz ~/data | age -r age1ql3z7hjy54pw3hyww5ayyfg7zqgvc7w3j2elw8zmrj2kg5sfn9aqmcac8p > data.tar.gz.age\n"
"    $ age --decrypt -i key.txt -o data.tar.gz data.tar.gz.age\n";

int main(int argc, char **argv) {
    if (argc == 1) {
        printf("%s", help_text);
        return 0;
    }
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--version") == 0) {
            printf("v0.0.0-20260414014000-96fce988442d\n");
            return 0;
        }
        if (strcmp(argv[i], "--help") == 0 || strcmp(argv[i], "-h") == 0)
        {
            printf("%s", help_text);
            return 0;
        }
    }
    /* Default: print help (original prints usage when run without args) */
    printf("%s", help_text);
    return 0;
}
EOF

cat > compile.sh <<'EOF'
#!/usr/bin/env bash
set -e
# Compile the small age-like CLI.
cc -o executable main.c
chmod +x executable
EOF

cat > .gitignore <<'EOF'
/executable
EOF

chmod +x compile.sh

# show files
ls -la
sed -n '1,200p' main.c
sed -n '1,200p' compile.sh
EOF"}

